var a=`0253-halloumi-saganaki`;var n=`world-0253`;var t=`CY`;var o=`western-asia`;var s=4;var l=13;var r={en:`Halloumi Saganaki`,ua:`Саганакі з халумі`};var u={en:`A traditional Cyprus dish made with halloumi, all-purpose flour, lemon juice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Кіпр. Основні інгредієнти: халумі, пшеничне борошно універсальне, лимонний сік. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:4,i:[[`halloumi`,480,`g`],[`all-purpose-flour`,45,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 7 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 7 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:7,i:[[`extra-virgin-olive-oil`,50,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon-juice`,30,`ml`],[`honey`,20,`g`]]}];var h={slug:a,id:n,country:`CY`,region:o,servings:4,minutes:13,title:r,text:u,steps:d};export{t as country,h as default,n as id,l as minutes,o as region,s as servings,a as slug,d as steps,u as text,r as title};